-- Integrity rules that schema.prisma cannot express: CHECK constraints,
-- triggers and the settings singletons. Written by hand; Prisma's schema diff
-- ignores CHECK constraints, functions and triggers, so later migrations
-- generated by `prisma migrate dev` never drop them.
--
-- Privileges for the runtime role are NOT set here (role names differ per
-- environment): see scripts/db/grants.ts, run after every migration.

-- ─── 1. Exactly one Admin ────────────────────────────────────────────────────
-- id defaults to 1 and is the primary key, and this CHECK forbids any other
-- value: a second Admin row is impossible (PK conflict on 1, CHECK on others).
ALTER TABLE "admin_user"
  ADD CONSTRAINT "admin_user_single_admin" CHECK ("id" = 1),
  ADD CONSTRAINT "admin_user_email_format" CHECK (
    "email" = lower("email")
    AND char_length("email") <= 254
    AND "email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  ADD CONSTRAINT "admin_user_name_not_blank" CHECK (btrim("name") <> ''),
  ADD CONSTRAINT "admin_user_password_hash_scrypt" CHECK ("password_hash" LIKE 'scrypt$%'),
  ADD CONSTRAINT "admin_user_failed_login_count_nonnegative" CHECK ("failed_login_count" >= 0);

COMMENT ON TABLE "admin_user" IS
  'The single Admin account. id is always 1 (CHECK admin_user_single_admin). Created only by scripts/admin/bootstrap.ts.';

-- ─── 2. Sessions: 8 hours from the last activity at most ─────────────────────
ALTER TABLE "admin_session"
  ADD CONSTRAINT "admin_session_token_hash_sha256" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "admin_session_timeline" CHECK ("last_seen_at" >= "created_at" AND "expires_at" > "last_seen_at"),
  ADD CONSTRAINT "admin_session_max_8_hours" CHECK ("expires_at" <= "last_seen_at" + interval '8 hours');

ALTER TABLE "login_attempt"
  ADD CONSTRAINT "login_attempt_reason_known" CHECK (
    "reason" IN ('ok', 'bad_credentials', 'locked', 'rate_limited', 'invalid_input')
  ),
  ADD CONSTRAINT "login_attempt_success_matches_reason" CHECK ("success" = ("reason" = 'ok'));

-- ─── 3. Editorial data ───────────────────────────────────────────────────────
ALTER TABLE "section"
  ADD CONSTRAINT "section_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length("slug") <= 80),
  ADD CONSTRAINT "section_name_not_blank" CHECK (btrim("name") <> '');

ALTER TABLE "author"
  ADD CONSTRAINT "author_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length("slug") <= 80),
  ADD CONSTRAINT "author_name_not_blank" CHECK (btrim("name") <> '');

ALTER TABLE "article"
  ADD CONSTRAINT "article_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length("slug") <= 120),
  ADD CONSTRAINT "article_title_not_blank" CHECK (btrim("title") <> ''),
  ADD CONSTRAINT "article_tags_not_null" CHECK ("tags" IS NOT NULL),
  ADD CONSTRAINT "article_version_positive" CHECK ("version" >= 1),
  ADD CONSTRAINT "article_reading_minutes_positive" CHECK ("reading_minutes" >= 1),
  ADD CONSTRAINT "article_canonical_url_https" CHECK ("canonical_url" IS NULL OR "canonical_url" ~ '^https://'),
  ADD CONSTRAINT "article_published_needs_date" CHECK ("status" <> 'PUBLISHED' OR "published_at" IS NOT NULL),
  ADD CONSTRAINT "article_published_needs_hero" CHECK ("status" <> 'PUBLISHED' OR "hero_media_id" IS NOT NULL),
  ADD CONSTRAINT "article_published_needs_section" CHECK (
    "status" <> 'PUBLISHED' OR "kanal_id" IS NOT NULL OR "rubrik_id" IS NOT NULL
  ),
  ADD CONSTRAINT "article_archived_needs_date" CHECK ("status" <> 'ARCHIVED' OR "archived_at" IS NOT NULL);

ALTER TABLE "article_slug_history"
  ADD CONSTRAINT "article_slug_history_slug_format" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$');

ALTER TABLE "article_revision"
  ADD CONSTRAINT "article_revision_version_positive" CHECK ("version" >= 1);

ALTER TABLE "article_media"
  ADD CONSTRAINT "article_media_position_nonnegative" CHECK ("position" >= 0);

-- A section's kind is fixed: kanal stays kanal, rubrik stays rubrik.
CREATE FUNCTION "section_kind_immutable"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."kind" IS DISTINCT FROM OLD."kind" THEN
    RAISE EXCEPTION 'section.kind cannot change (% → %)', OLD."kind", NEW."kind"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "section_kind_immutable"
  BEFORE UPDATE OF "kind" ON "section"
  FOR EACH ROW EXECUTE FUNCTION "section_kind_immutable"();

-- article.kanal_id must point at a KANAL, article.rubrik_id at a RUBRIK.
CREATE FUNCTION "article_check_section_kinds"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."kanal_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "section" WHERE "id" = NEW."kanal_id" AND "kind" = 'KANAL'
  ) THEN
    RAISE EXCEPTION 'article.kanal_id must reference an existing KANAL section'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."rubrik_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "section" WHERE "id" = NEW."rubrik_id" AND "kind" = 'RUBRIK'
  ) THEN
    RAISE EXCEPTION 'article.rubrik_id must reference an existing RUBRIK section'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "article_section_kinds"
  BEFORE INSERT OR UPDATE OF "kanal_id", "rubrik_id" ON "article"
  FOR EACH ROW EXECUTE FUNCTION "article_check_section_kinds"();

-- Slug history: a renamed article keeps its old URL (301 to the new slug).
-- A slug that becomes live again stops redirecting.
CREATE FUNCTION "article_track_slug"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM "article_slug_history" WHERE "slug" = NEW."slug";
  IF TG_OP = 'UPDATE' AND NEW."slug" IS DISTINCT FROM OLD."slug" THEN
    INSERT INTO "article_slug_history" ("slug", "article_id")
    VALUES (OLD."slug", NEW."id")
    ON CONFLICT ("slug") DO UPDATE SET "article_id" = EXCLUDED."article_id", "created_at" = now();
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER "article_slug_history"
  AFTER INSERT OR UPDATE OF "slug" ON "article"
  FOR EACH ROW EXECUTE FUNCTION "article_track_slug"();

-- Status history: every status an article enters is recorded.
CREATE FUNCTION "article_track_status"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO "article_status_change" ("article_id", "from_status", "to_status")
    VALUES (NEW."id", NULL, NEW."status");
  ELSIF NEW."status" IS DISTINCT FROM OLD."status" THEN
    INSERT INTO "article_status_change" ("article_id", "from_status", "to_status")
    VALUES (NEW."id", OLD."status", NEW."status");
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER "article_status_history"
  AFTER INSERT OR UPDATE OF "status" ON "article"
  FOR EACH ROW EXECUTE FUNCTION "article_track_status"();

-- ─── 4. Media ────────────────────────────────────────────────────────────────
ALTER TABLE "media"
  ADD CONSTRAINT "media_sha256_hex" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "media_size_positive" CHECK ("size_bytes" > 0),
  ADD CONSTRAINT "media_dimensions_positive" CHECK (
    ("width" IS NULL OR "width" > 0) AND ("height" IS NULL OR "height" > 0)
  ),
  ADD CONSTRAINT "media_variants_array" CHECK (jsonb_typeof("variants") = 'array');

ALTER TABLE "media_folder"
  ADD CONSTRAINT "media_folder_name_not_blank" CHECK (btrim("name") <> '');

-- ─── 5. Homepage & site settings (singletons) ────────────────────────────────
ALTER TABLE "homepage_settings"
  ADD CONSTRAINT "homepage_settings_singleton" CHECK ("id" = 1),
  ADD CONSTRAINT "homepage_settings_latest_count_range" CHECK ("latest_count" BETWEEN 1 AND 24);

ALTER TABLE "homepage_featured"
  ADD CONSTRAINT "homepage_featured_position_range" CHECK ("position" BETWEEN 0 AND 11);

ALTER TABLE "homepage_rubric"
  ADD CONSTRAINT "homepage_rubric_position_range" CHECK ("position" BETWEEN 0 AND 5),
  ADD CONSTRAINT "homepage_rubric_item_count_range" CHECK ("item_count" BETWEEN 1 AND 12);

ALTER TABLE "site_settings"
  ADD CONSTRAINT "site_settings_singleton" CHECK ("id" = 1),
  ADD CONSTRAINT "site_settings_social_links_object" CHECK (jsonb_typeof("social_links") = 'object');

-- Homepage bands only feature rubrik sections.
CREATE FUNCTION "homepage_rubric_check_kind"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "section" WHERE "id" = NEW."section_id" AND "kind" = 'RUBRIK') THEN
    RAISE EXCEPTION 'homepage_rubric.section_id must reference an existing RUBRIK section'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "homepage_rubric_kind"
  BEFORE INSERT OR UPDATE OF "section_id" ON "homepage_rubric"
  FOR EACH ROW EXECUTE FUNCTION "homepage_rubric_check_kind"();

-- The singleton rows always exist, so the app never has to create them.
INSERT INTO "homepage_settings" ("id", "updated_at") VALUES (1, now()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "site_settings" ("id", "updated_at") VALUES (1, now()) ON CONFLICT ("id") DO NOTHING;

-- ─── 6. Activity Log: append-only ────────────────────────────────────────────
ALTER TABLE "activity_log"
  ADD CONSTRAINT "activity_log_action_format" CHECK ("action" ~ '^[a-z][a-z_]*(\.[a-z][a-z_]*)+$'),
  ADD CONSTRAINT "activity_log_admin_actor_has_admin" CHECK ("actor" <> 'ADMIN' OR "admin_id" IS NOT NULL),
  ADD CONSTRAINT "activity_log_meta_object" CHECK (jsonb_typeof("meta") = 'object');

-- Any UPDATE, DELETE or TRUNCATE statement on activity_log fails, whoever runs
-- it — even if it would touch zero rows. Only INSERT is possible.
CREATE FUNCTION "activity_log_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'activity_log is append-only: % is not allowed', TG_OP
    USING HINT = 'Audit entries can only be added, never changed or removed.';
END $$;

CREATE TRIGGER "activity_log_append_only"
  BEFORE UPDATE OR DELETE OR TRUNCATE ON "activity_log"
  FOR EACH STATEMENT EXECUTE FUNCTION "activity_log_append_only"();

-- The time of an entry is always the database's, never the client's.
CREATE FUNCTION "activity_log_stamp"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW."created_at" := now();
  RETURN NEW;
END $$;

CREATE TRIGGER "activity_log_stamp"
  BEFORE INSERT ON "activity_log"
  FOR EACH ROW EXECUTE FUNCTION "activity_log_stamp"();

COMMENT ON TABLE "activity_log" IS
  'Append-only audit trail. UPDATE/DELETE/TRUNCATE are rejected by trigger activity_log_append_only; the app role also lacks those privileges.';
